/**
 * Cloudflare configuration. Generated by `cf migrate` from the wrangler
 * config it replaced; the comments below are ours.
 *
 * The bundler-specific half — the `#env` alias and the assets directory —
 * lives in `wrangler.config.ts`, because this Worker is not a Vite project and
 * `cf` bundles it through wrangler.
 */

import { bindings, defineConfig, triggers } from "cf/config";

export default defineConfig({
  worker: {
    name: "id-kbn-one",
    compatibilityDate: "2026-10-19",

    // Written by `scripts/cf-build.sh`: `deno bundle` produces it, because
    // the source resolves JSR specifiers and workspace import maps that
    // esbuild knows nothing about. That bundle leaves `#env` unresolved on
    // purpose, for the alias in `wrangler.config.ts` to supply.
    entrypoint: "main/worker/worker.js",

    // The IdP's only origin. Applied on deploy, so the DNS record comes with
    // it — nothing to set up in the dashboard. The zone `kbn.one` has to be on
    // this same account for that.
    domains: ["id.kbn.one"],

    // An identity provider answering on a second hostname is not useful here
    // and is worth avoiding: `IDP_ORIGIN` — the `iss` of every token it signs
    // — names `id.kbn.one`, and a passkey cannot be used from a workers.dev
    // host anyway, because `RP_ID` is `kbn.one`.
    workersDev: false,
    // On, to match the dashboard. When the Worker was last changed in the
    // dashboard, `cf deploy` compares this file with the dashboard settings and
    // asks before turning anything off; Workers Builds cannot answer, so the
    // deploy stops there. Left out, this setting reads as off (the Worker has
    // a custom domain), which is exactly such a change.
    //
    // Preview URLs are per-version hosts on workers.dev, which the paragraph
    // above keeps off for the IdP itself. Switching them off is a separate
    // change, safe to make once a deploy from here has gone through.
    previewUrls: true,

    observability: {
      enabled: true,
    },

    // D1 has no TTL of its own. Reads already treat an expired row as absent,
    // so this only reclaims storage and a missed run costs nothing but space.
    triggers: [
      triggers.scheduled({
        schedule: "23 4 * * *",
      }),
    ],

    env: {
      // Public configuration, not secrets: the signing key lives in D1. Copied
      // from the Deno Deploy dashboard, where they were only ever set.
      //
      // Do not change `RP_ID`. A WebAuthn credential is bound to the RP ID it
      // was created under, so a different value here makes every existing
      // passkey unusable, and putting it back does not bring them back — the
      // authenticator keeps the original binding. It is the registrable suffix
      // `kbn.one`, not the IdP's own host, which is why `https://id.kbn.one`
      // is a valid origin for it.
      RP_ID: bindings.text("kbn.one"),
      RP_NAME: bindings.text("kbn.one"),
      IDP_ORIGIN: bindings.text("https://id.kbn.one"),
      // Hostnames, subdomains included. Carried over as production had it; the
      // deno.net entries can go once nothing redirects there any more.
      AUTHORIZE_WHITELIST: bindings.text(
        "kbn.one,kbn.deno.net,kuboon-tokyo.deno.net,kuboon.github.io," +
          "kuboon.workers.dev,localhost",
      ),
      PUSH_CONTACT: bindings.text("mailto:o@kbn.one"),
      // Bearer token for the home portal agent that feedback is reported
      // through (endpoint and home are fixed in `main/server/config.ts`). A
      // declared secret is required: a deploy fails until it is set on the
      // Worker, rather than shipping a Worker that silently stops reporting.
      HOME_PORTAL_MCP_TOKEN: bindings.secret(),

      // Deno KV's replacement, already holding the migrated data. D1 rather
      // than Workers KV because the app needs compare-and-set: single-use
      // OAuth codes, refresh-token reuse detection, DPoP replay rejection and
      // push rate limiting all rest on it, and Workers KV would keep returning
      // success while those guarantees quietly vanished.
      DB: bindings.d1({
        name: "id-kbn-one",
        id: "1ad1c197-5119-4392-bf55-e863fe70334e",
      }),
    },
  },
});
